    hash.bhp256 r284 into r285 as field;
    call token_registry.aleo/transfer_private_to_public arcn_pool_v2_2_2.aleo r2 r1 into r286 r287;
    call token_registry.aleo/transfer_private_to_public arcn_pool_v2_2_2.aleo r4 r3 into r288 r289;
