    cast r0 r1.token_id r3.token_id r285 r6 into r291 as LpTokenReceipt.record;
    is.eq r7 0u8 into r292;
    is.eq r7 1u8 into r293;
    ternary r293 r283 0u128 into r294;
    ternary r292 r26 r294 into r295;
    gte r295 100000000u128 into r296;
    assert.eq r296 true;
    is.neq self.caller self.signer into r297;
    ternary r297 self.caller aleo1qqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqq3ljyzc into r298;
    call arcn_whitelist.aleo/is_caller_eligible r298 into r299;
    async create_pool r287 r289 r299 r285 r1.token_id r2 r3.token_id r4 r5 r25 r7 r295 r8 into r300;
