    is.eq r9.token1_id r4 into r13;
    is.eq r9.token2_id r4 into r14;
    or r13 r14 into r15;
    assert.eq r15 true;
    remove amm_deposits[r0];
    set r8 into amm_deposits[r1];
    branch.eq true true to end_otherwise_0_1;
